const computeRegimeV10736=(bars,drift1m,drift5m,drift15m,atrBps)=>{
  if(!bars||bars.length<30)return null;
  const closes=bars.map(b=>b.c);
  const n=closes.length;
  // V10.7.44 FIX: closes is newest-first. closes[n-1] is the OLDEST bar.
  // currentClose must be closes[0] (most recent bar).
  const currentClose=closes[0];
  // 1. ADX
  const {adx,valid:adxValid}=computeADX(bars,14);
  // 2. BBW percentile
  const {bbw,rank:bbwRank}=computeBBWRank(closes,_bbwHistory,100);
  // 3. Whipsaw filter
  const whipsawCount=computeWhipsawCount(bars,20,10);
  const isWhipsawing=whipsawCount>=3;
  // 4. ATRP
  const {atrp,regime:atrpRegime}=computeATRP(bars,2,14);
  // 5. Median filter for direction in chop (AiBitcoinTrend)
  const medianPrice=computeMedianFilter(closes,Math.min(50,Math.floor(n/2)));
  const priceAboveMedian=currentClose>medianPrice;
  // 6. Regime determination (Master Regime Classifier V6.2 logic)
  const isHighVol=bbwRank>=80||atrpRegime==='Extreme'||(atrBps&&atrBps>40);
  const isTrend=!isHighVol&&adxValid&&adx>=20&&!isWhipsawing;
  const isChop=!isHighVol&&!isTrend;

  // V10.7.75b — COMPRESSING regime detection
  //   Pattern: BBW percentile is LOW (tight range) AND has been FALLING (contracting).
  //   This is the pre-breakout coil — direction unknown, explosive move imminent.
  //   Detection: current BBW rank < 30th pct AND falling from prior 5 readings.
  const _bbwRecent=_bbwHistory.slice(-6);
  const _bbwFalling=_bbwRecent.length>=5&&_bbwRecent[_bbwRecent.length-1]<_bbwRecent[0]*0.85;
  const isCompressing=isChop&&bbwRank<30&&_bbwFalling&&!isWhipsawing;

  // Determine direction within TREND
  const driftUp=drift1m>3&&drift5m>5;
  const driftDn=drift1m<-3&&drift5m<-5;
  let regimeV2=isHighVol?'HIGH VOL CHOP'
    :isCompressing?'COMPRESSING'
    :isTrend?(driftUp?'TRENDING UP':driftDn?'TRENDING DOWN':'RANGE-CHOP')
    :'RANGE-CHOP';
  return{
    regime:regimeV2,
    adx,bbwRank,bbw,isWhipsawing,whipsawCount,
    atrp,atrpRegime,priceAboveMedian,medianPrice,
    isHighVol,isTrend,isChop,isCompressing,
    _v10_7_36:true,
  };
};
const detectChartPattern=(history)=>{
  if(!history||history.length<10)return{pattern:null,confidence:0};
  const recent=history.slice(0,15); // last 15 candles
  const highs=recent.map(c=>c.h||c.c||0);
  const lows=recent.map(c=>c.l||c.c||0);
  const closes=recent.map(c=>c.c||0);
  // Find peaks (local maxima) and troughs (local minima)
  const peaks=[],troughs=[];
  for(let i=1;i<recent.length-1;i++){
    if(highs[i]>highs[i-1]&&highs[i]>highs[i+1])peaks.push({i,p:highs[i]});
    if(lows[i]<lows[i-1]&&lows[i]<lows[i+1])troughs.push({i,p:lows[i]});
  }
  // Double Top: 2 peaks within 0.3% of each other, separated by 3+ candles
  if(peaks.length>=2){
    const[p1,p2]=peaks.slice(-2);
    const diff=Math.abs(p1.p-p2.p)/p2.p;
    if(diff<0.003&&Math.abs(p1.i-p2.i)>=3){
      return{pattern:'doubleTop',confidence:0.7,detail:`Resistance at $${p1.p.toFixed(0)}`};
    }
  }
  // Double Bottom: 2 troughs within 0.3% of each other
  if(troughs.length>=2){
    const[t1,t2]=troughs.slice(-2);
    const diff=Math.abs(t1.p-t2.p)/t2.p;
    if(diff<0.003&&Math.abs(t1.i-t2.i)>=3){
      return{pattern:'doubleBottom',confidence:0.7,detail:`Support at $${t1.p.toFixed(0)}`};
    }
  }
  // Wedge: highs decreasing AND lows increasing (compression)
  if(peaks.length>=2&&troughs.length>=2){
    const peakSlope=(peaks[peaks.length-1].p-peaks[0].p)/(peaks[peaks.length-1].i-peaks[0].i||1);
    const troughSlope=(troughs[troughs.length-1].p-troughs[0].p)/(troughs[troughs.length-1].i-troughs[0].i||1);
    // Descending highs, ascending lows = symmetrical triangle (breakout imminent)
    if(peakSlope<-2&&troughSlope>2){
      return{pattern:'compression',confidence:0.6,detail:'Symmetrical triangle — breakout imminent'};
    }
    // Ascending wedge (rising channel) = often bearish
    if(peakSlope>0&&troughSlope>0&&peakSlope<troughSlope){
      return{pattern:'wedgeUp',confidence:0.5,detail:'Rising wedge — bearish bias'};
    }
    // Descending wedge = often bullish
    if(peakSlope<0&&troughSlope<0&&peakSlope>troughSlope){
      return{pattern:'wedgeDn',confidence:0.5,detail:'Falling wedge — bullish bias'};
    }
  }
  return{pattern:null,confidence:0};
};
const detectTrendStructure=(history)=>{
  if(!history||history.length<8)return{trend:null,strength:0};
  const recent=history.slice(0,20);
  const highs=recent.map(c=>c.h||c.c||0);
  const lows=recent.map(c=>c.l||c.c||0);
  const peaks=[],troughs=[];
  for(let i=1;i<recent.length-1;i++){
    if(highs[i]>highs[i-1]&&highs[i]>highs[i+1])peaks.push({i,p:highs[i]});
    if(lows[i]<lows[i-1]&&lows[i]<lows[i+1])troughs.push({i,p:lows[i]});
  }
  // Need at least 2 of each to compare
  if(peaks.length<2||troughs.length<2)return{trend:null,strength:0};
  // Use the most recent 3 pivots if available, else last 2
  const lastPeaks=peaks.slice(-3);
  const lastTroughs=troughs.slice(-3);
  // Higher-Highs: each peak strictly higher than the previous
  let _hhCount=0;
  for(let i=1;i<lastPeaks.length;i++){if(lastPeaks[i].p>lastPeaks[i-1].p)_hhCount++;}
  // Lower-Highs: each peak strictly lower than the previous
  let _lhCount=0;
  for(let i=1;i<lastPeaks.length;i++){if(lastPeaks[i].p<lastPeaks[i-1].p)_lhCount++;}
  // Higher-Lows / Lower-Lows on troughs
  let _hlCount=0,_llCount=0;
  for(let i=1;i<lastTroughs.length;i++){
    if(lastTroughs[i].p>lastTroughs[i-1].p)_hlCount++;
    if(lastTroughs[i].p<lastTroughs[i-1].p)_llCount++;
  }
  // Score: 0-1 based on how many pivots agree
  const _maxPossible=Math.max(lastPeaks.length-1,1)+Math.max(lastTroughs.length-1,1);
  // Uptrend: HH AND HL
  if(_hhCount>=1&&_hlCount>=1){
    const strength=(_hhCount+_hlCount)/_maxPossible;
    return{trend:'UP',strength,detail:`${_hhCount} higher-high${_hhCount>1?'s':''} + ${_hlCount} higher-low${_hlCount>1?'s':''}`};
  }
  // Downtrend: LH AND LL
  if(_lhCount>=1&&_llCount>=1){
    const strength=(_lhCount+_llCount)/_maxPossible;
    return{trend:'DOWN',strength,detail:`${_lhCount} lower-high${_lhCount>1?'s':''} + ${_llCount} lower-low${_llCount>1?'s':''}`};
  }
  return{trend:null,strength:0};
};
const detectTrendlineBreak=(history)=>{
  if(!history||history.length<8)return{broke:null,magnitudeBps:0};
  const recent=history.slice(0,15);
  const highs=recent.map(c=>c.h||c.c||0);
  const lows=recent.map(c=>c.l||c.c||0);
  const peaks=[],troughs=[];
  for(let i=1;i<recent.length-1;i++){
    if(highs[i]>highs[i-1]&&highs[i]>highs[i+1])peaks.push({i,p:highs[i]});
    if(lows[i]<lows[i-1]&&lows[i]<lows[i+1])troughs.push({i,p:lows[i]});
  }
  const currentClose=recent[0]?.c;
  if(!Number.isFinite(currentClose)||currentClose<=0)return{broke:null,magnitudeBps:0};
  // Use the most recent 3 pivots. Need at least 3 to fit a meaningful line.
  // We're looking at index-position, NOT time. recent[0] is most recent candle,
  //   peaks/troughs are at indices into `recent`. Lower index = more recent.
  const lastPeaks=peaks.slice(-3);
  const lastTroughs=troughs.slice(-3);
  // Helper: fit a line through points, get expected y at the current candle's x (idx=0).
  //   Linear regression on the (i, p) points returns slope/intercept; predict at i=0.
  const _predictAt0=(pivots)=>{
    if(pivots.length<2)return null;
    const n=pivots.length;
    let sumX=0,sumY=0,sumXY=0,sumXX=0;
    for(const p of pivots){sumX+=p.i;sumY+=p.p;sumXY+=p.i*p.p;sumXX+=p.i*p.i;}
    const denom=(n*sumXX)-(sumX*sumX);
    if(denom===0)return null;
    const slope=((n*sumXY)-(sumX*sumY))/denom;
    const intercept=(sumY-(slope*sumX))/n;
    return slope*0+intercept;
  };
  // Check support break (rising lows trendline broken to the downside)
  if(lastTroughs.length>=3){
    // Confirm rising lows first — slope must be positive (i.e., earlier pivots at higher
    //   indices have lower prices; pivots[length-1] is the most-recent low). Since
    //   lower index = more recent, "rising lows" means most-recent low > earlier lows.
    const _t0=lastTroughs[lastTroughs.length-1].p; // earliest in array = oldest
    const _tLast=lastTroughs[0].p; // first in array = most recent
    if(_tLast>_t0){
      // Rising support — check if current close broke below predicted line
      const _expected=_predictAt0(lastTroughs);
      if(_expected!=null){
        const _diffBps=((currentClose-_expected)/_expected)*10000;
        // Break = current price meaningfully BELOW the line
        if(_diffBps<-5){
          return{broke:'UP',magnitudeBps:Math.abs(Math.round(_diffBps)),detail:`Rising support broken (${Math.abs(Math.round(_diffBps))}bps below trendline)`};
        }
      }
    }
  }
  // Check resistance break (falling highs trendline broken to the upside)
  if(lastPeaks.length>=3){
    const _p0=lastPeaks[lastPeaks.length-1].p;
    const _pLast=lastPeaks[0].p;
    if(_pLast<_p0){
      // Falling resistance — check if current close broke above predicted line
      const _expected=_predictAt0(lastPeaks);
      if(_expected!=null){
        const _diffBps=((currentClose-_expected)/_expected)*10000;
        if(_diffBps>5){
          return{broke:'DOWN',magnitudeBps:Math.abs(Math.round(_diffBps)),detail:`Falling resistance broken (${Math.abs(Math.round(_diffBps))}bps above trendline)`};
        }
      }
    }
  }
  return{broke:null,magnitudeBps:0};
};
const _normalizeCandles=(candles)=>{
  if(!Array.isArray(candles)||candles.length<2)return candles||[];
  const _t0=Number(candles[0]?.time)||0;
  const _t1=Number(candles[1]?.time)||0;
  if(_t0<_t1)return [...candles].reverse(); // was oldest-first → newest-first
  return candles;
};
const detectHtfPatterns=(tfCandles)=>{
  const _emptyResult={perTF:{c1m:null,c5m:null,c15m:null},totalAdj:0,directionalScore:0,confluence:0,dominantDirection:null,detail:'no HTF data'};
  if(!tfCandles)return _emptyResult;
  // Per-TF weights. Higher TF = more reliable signal for 15m Kalshi windows.
  const _tfWeights={c1m:1.0,c5m:1.5,c15m:2.0};
  // Per-detector base weight contributions (mirror V9.10.10's choices)
  const _detectorWeights={
    doubleTop:-20, doubleBottom:+20, wedgeUp:-10, wedgeDn:+10, compression:0,
    trendUP:+15, trendDOWN:-15, // scaled by strength
    tlBreakUP:-20, tlBreakDOWN:+20, // 'UP' broke = bearish; 'DOWN' broke = bullish
  };
  const _perTF={};
  let _totalAdj=0;
  // Track per-TF directional score so we can compute confluence
  const _tfDirScore={c1m:0,c5m:0,c15m:0};
  for(const _tf of ['c1m','c5m','c15m']){
    const _raw=tfCandles[_tf];
    if(!Array.isArray(_raw)||_raw.length<8){_perTF[_tf]=null;continue;}
    const _norm=_normalizeCandles(_raw);
    // Run all three detectors
    const _cp=detectChartPattern(_norm);
    const _ts=detectTrendStructure(_norm);
    const _tl=detectTrendlineBreak(_norm);
    // Compute this TF's contribution
    let _tfAdj=0;
    const _reasons=[];
    if(_cp?.pattern){
      const _w=_detectorWeights[_cp.pattern]||0;
      if(_w){_tfAdj+=_w; _reasons.push(`${_cp.pattern}(${_w>0?'+':''}${_w})`);}
    }
    if(_ts?.trend){
      const _baseW=_ts.trend==='UP'?_detectorWeights.trendUP:_detectorWeights.trendDOWN;
      const _scaled=Math.round(_baseW*(_ts.strength||0));
      if(_scaled){_tfAdj+=_scaled; _reasons.push(`${_ts.trend}-trend(${_scaled>0?'+':''}${_scaled})`);}
    }
    if(_tl?.broke){
      const _w=_tl.broke==='UP'?_detectorWeights.tlBreakUP:_detectorWeights.tlBreakDOWN;
      _tfAdj+=_w; _reasons.push(`${_tl.broke==='UP'?'support-broken':'resistance-broken'}(${_w>0?'+':''}${_w})`);
    }
    // Apply TF weight
    const _weighted=Math.round(_tfAdj*_tfWeights[_tf]);
    _tfDirScore[_tf]=_tfAdj;
    _totalAdj+=_weighted;
    _perTF[_tf]={
      pattern:_cp?.pattern||null,
      trend:_ts?.trend||null,
      tlBreak:_tl?.broke||null,
      rawAdj:_tfAdj,
      weightedAdj:_weighted,
      reasons:_reasons.join('+')||null,
    };
  }
  // Confluence: count how many TFs agree on net direction
  const _signs=Object.values(_tfDirScore).filter(s=>Math.abs(s)>=5).map(s=>s>0?1:-1);
  const _upCount=_signs.filter(s=>s>0).length;
  const _downCount=_signs.filter(s=>s<0).length;
  let _confluence=0;
  let _dominantDir=null;
  let _confBonus=0;
  if(_upCount>=2&&_downCount===0){_confluence=_upCount; _dominantDir='UP';}
  else if(_downCount>=2&&_upCount===0){_confluence=_downCount; _dominantDir='DOWN';}
  if(_confluence>=2){
    // Apply confluence bonus: 30% for 2-TF, 60% for 3-TF
    const _bonusMult=_confluence===3?1.6:1.3;
    _totalAdj=Math.round(_totalAdj*_bonusMult);
    _confBonus=Math.round(_totalAdj*(1-1/_bonusMult)); // approx amount added
  }
  // Build detail string
  const _details=[];
  for(const _tf of ['c1m','c5m','c15m']){
    const _t=_perTF[_tf];
    if(_t&&_t.reasons)_details.push(`${_tf.slice(1)}:${_t.reasons}`);
  }
  const _detail=_details.length>0
    ?(_details.join(' | ')+(_confluence>=2?` · ${_confluence}-TF confluence ${_dominantDir}`:''))
    :'no patterns detected';
  return{
    perTF:_perTF,
    totalAdj:_totalAdj,
    directionalScore:_totalAdj,
    confluence:_confluence,
    dominantDirection:_dominantDir,
    confluenceBonusAdj:_confBonus,
    detail:_detail,
  };
};
const _weightOf=(W,key)=>{
  const _v=(W&&typeof W==='object')?W[key]:undefined;
  if(typeof _v==='number'&&Number.isFinite(_v))return _v;
  const _d=DEFAULT_WEIGHTS[key];
  return (typeof _d==='number'&&Number.isFinite(_d))?_d:1.0;
};
const computeFuturesSignals=({funding,oi,oiDelta,basis,basisPct,drift1m})=>{
  const out={fundingAdj:0,oiAdj:0,basisAdj:0,totalAdj:0,details:[]};
  // Funding signal — mean-reversion bias on extremes
  if(Number.isFinite(funding)){
    const _fundingPct=funding*100; // convert decimal to percent
    // Threshold at 0.02% (modest), max at 0.05% (extreme)
    const _absF=Math.abs(_fundingPct);
    if(_absF>=0.02){
      const _scale=Math.min(1.0,(_absF-0.02)/(0.05-0.02));
      const _adj=Math.round(15*_scale);
      // Positive funding (longs paying shorts) → bias toward DOWN unwind
      out.fundingAdj=funding>0?-_adj:+_adj;
      out.details.push(`funding ${_fundingPct.toFixed(3)}% → ${out.fundingAdj>0?'+':''}${out.fundingAdj}`);
    }
  }
  // OI delta signal
  // V9.11.2: bloomberg.oiChange5m is a 5-minute window (not 30s). Real OI moves of
  //   conviction are often 2-5% per 5min during big drives. Raised threshold to
  //   ≥1.5% to filter noise; was ≥0.5% which made sense for 30s data.
  if(Number.isFinite(oiDelta)&&Number.isFinite(drift1m)){
    if(Math.abs(oiDelta)>=1.5&&Math.abs(drift1m)>=3){
      if(oiDelta>0&&drift1m>0){
        out.oiAdj=+8;
        out.details.push(`OI ↑${oiDelta.toFixed(1)}%/5m + price ↑${drift1m.toFixed(1)}bps → +8 conviction UP`);
      } else if(oiDelta>0&&drift1m<0){
        out.oiAdj=-8;
        out.details.push(`OI ↑${oiDelta.toFixed(1)}%/5m + price ↓${drift1m.toFixed(1)}bps → -8 shorts opening`);
      }
      // OI falling = position closing = no directional signal
    }
  }
  // Basis signal — mean-reversion bias on extremes
  if(Number.isFinite(basisPct)){
    const _absB=Math.abs(basisPct);
    // Threshold at 0.05% (modest), max at 0.15% (extreme)
    if(_absB>=0.05){
      const _scale=Math.min(1.0,(_absB-0.05)/(0.15-0.05));
      const _adj=Math.round(10*_scale);
      out.basisAdj=basisPct>0?-_adj:+_adj; // positive basis → DOWN bias (overheated)
      out.details.push(`basis ${basisPct.toFixed(3)}% → ${out.basisAdj>0?'+':''}${out.basisAdj}`);
    }
  }
  out.totalAdj=out.fundingAdj+out.oiAdj+out.basisAdj;
  return out;
};
