    const _v1055IsSqueeze=_v1055Regime==='SHORT SQUEEZE';
    const _v1055IsLongSqueeze=_v1055Regime==='LONG SQUEEZE';
    const _v1055IsHighVolChop=_v1055Regime==='HIGH VOL CHOP';
